WITH valid_subscriptions AS (SELECT * FROM subscriptions WHERE status = 'PAUSED'), monthly_fee_bucket_summary AS (SELECT CASE WHEN monthly_fee >= 232 THEN 'high' WHEN monthly_fee >= 121 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, COUNT(DISTINCT monthly_fee) AS unique_customers, MAX(monthly_fee) AS max_monthly_fee FROM valid_subscriptions GROUP BY CASE WHEN monthly_fee >= 232 THEN 'high' WHEN monthly_fee >= 121 THEN 'mid' ELSE 'low' END) SELECT monthly_fee_bucket, unique_customers, max_monthly_fee FROM monthly_fee_bucket_summary ORDER BY monthly_fee_bucket ASC
